import Fastify from "fastify";
import { init } from "../../src/dev-server/init";
import { normalize, serverDefaults } from "../../src/dev-server/config";

const __supportDir = __dirname + "/support";
const jsonPayload = { foo: "bar", llama: "wombat" };
const htmlPayload = `<div id="app"></div>`;
const upstreamErrorText = "Upstream 404";

describe("Config", () => {
  test("has sane defaults", () => {
    const config = normalize();
    expect(config.dirs[0]).toBe(".");
    expect(config.port).toBe(8080);
    for (const [k, v] of Object.entries(serverDefaults)) {
      expect((config.server as Record<string, unknown>)[k]).toBe(v);
    }
  });

  test("normalizes a directory string", () => {
    const config = normalize("dist");
    expect(typeof config).toBe("object");
    expect(config.dirs[0]).toBe("dist");
  });

  test("processes a config object", () => {
    const config = normalize({ dirs: ["foo", "bar"], port: 9090 });
    expect(config.dirs).toHaveLength(2);
    expect(config.port).toBe(9090);
  });

  test("config object can have server options", () => {
    const config = normalize({ port: 9090, server: { https: true } });
    expect(config.server.https).toBe(true);
    for (const [k, v] of Object.entries(serverDefaults)) {
      expect((config.server as Record<string, unknown>)[k]).toBe(v);
    }
    expect(config.port).toBe(9090);
  });

  test("accepts httpProxy option", () => {
    const config = normalize({ httpProxy: "http://proxy.example.com:8080" });
    expect(config.httpProxy).toBe("http://proxy.example.com:8080");
  });

  test("throws on invalid attributes", () => {
    expect(() => normalize({ dirs: "whoops" } as any)).toThrow();
  });
});

describe("Dirs", () => {
  let server: any;

  beforeAll(async () => {
    server = await init({
      dirs: ["support"],
      dirname: __supportDir + "/..",
      silent: true,
      server: { ...serverDefaults },
    });
  });

  afterAll(async () => {
    await server.close();
  });

  test("serves", async () => {
    const res = await server.inject().get("/200.html");
    expect(res.statusCode).toBe(200);
    expect(res.body.trim()).toBe("success");
  });

  test("404s", async () => {
    const res = await server.inject().get("/404.html");
    expect(res.statusCode).toBe(404);
  });

  test("works without dirname (run from project root)", async () => {
    const s = await init({
      dirs: ["test/dev-server/support"],
      silent: true,
      server: { ...serverDefaults },
    });
    const res = await s.inject().get("/200.html");
    expect(res.statusCode).toBe(200);
    await s.close();
  });
});

describe("Spa", () => {
  let server: any;
  let upstreamServer: any;

  beforeAll(async () => {
    upstreamServer = Fastify();
    upstreamServer.get("/404", async (_: any, reply: any) =>
      reply.code(404).send(upstreamErrorText),
    );
    await upstreamServer.ready();
    await upstreamServer.listen({ port: 12345 });

    server = await init({
      dirs: ["support"],
      spa: "200.html",
      proxy: [{ from: "/404-proxy", to: "http://localhost:12345/404" }],
      dirname: __supportDir + "/..",
      silent: true,
      server: { ...serverDefaults },
    });
  });

  afterAll(async () => {
    await server.close();
    await upstreamServer.close();
  });

  test("serves", async () => {
    const res = await server.inject().get("/200.html");
    expect(res.statusCode).toBe(200);
    expect(res.body.trim()).toBe("success");
  });

  test("won't 404", async () => {
    const res = await server.inject().get("/404.html");
    expect(res.statusCode).toBe(200);
    expect(res.body.trim()).toBe("success");
  });

  test("allows 404s from upstream API", async () => {
    const res = await server.inject().get("/404-proxy");
    expect(res.statusCode).toBe(404);
    expect(res.body).toBe(upstreamErrorText);
  });

  test("works without dirname (run from project root)", async () => {
    const s = await init({
      dirs: ["test/dev-server/support"],
      spa: "200.html",
      silent: true,
      server: { ...serverDefaults },
    });
    const fileRes = await s.inject().get("/200.html");
    expect(fileRes.statusCode).toBe(200);
    const spaRes = await s.inject().get("/404.html");
    expect(spaRes.statusCode).toBe(200);
    await s.close();
  });
});

describe("Proxy", () => {
  let server: any;
  let upstreamServer: any;

  beforeAll(async () => {
    upstreamServer = Fastify();
    upstreamServer.get("/json", async (_: any, reply: any) =>
      reply.send(jsonPayload),
    );
    upstreamServer.get("/html", async (_: any, reply: any) =>
      reply.type("text/html").send(htmlPayload),
    );
    await upstreamServer.ready();
    await upstreamServer.listen({ port: 12345 });

    server = await init({
      dirs: ["support"],
      dirname: __supportDir + "/..",
      proxy: [
        { from: "/api", to: "http://localhost:12345" },
        { from: "/just-json", to: "http://localhost:12345/json" },
      ],
      silent: true,
      server: { ...serverDefaults },
    });
  });

  afterAll(async () => {
    await server.close();
    await upstreamServer.close();
  });

  test("can get json", async () => {
    const res = await server.inject().get("/api/json");
    expect(res.headers["content-type"]).toContain("application/json");
    expect(res.body).toBe(JSON.stringify(jsonPayload));
  });

  test("can get html", async () => {
    const res = await server.inject().get("/api/html");
    expect(res.headers["content-type"]).toContain("text/html");
    expect(res.body).toBe(htmlPayload);
  });

  test("can proxy to subpaths", async () => {
    const res = await server.inject().get("/just-json");
    expect(res.headers["content-type"]).toContain("application/json");
    expect(res.body).toBe(JSON.stringify(jsonPayload));
  });
});

describe("Basepath", () => {
  const basePath = "/my-app";
  let server: any;

  beforeAll(async () => {
    server = await init({
      dirs: ["support"],
      dirname: __supportDir + "/..",
      basePath,
      silent: true,
      server: { ...serverDefaults },
    });
  });

  afterAll(async () => {
    await server.close();
  });

  test("serves", async () => {
    const res = await server.inject().get("/my-app/200.html");
    expect(res.statusCode).toBe(200);
    expect(res.body.trim()).toBe("success");
  });

  test("404s", async () => {
    const res = await server.inject().get("/my-app/404.html");
    expect(res.statusCode).toBe(404);
  });

  test("can run spa under basepath", async () => {
    const s = await init({
      dirs: ["support"],
      dirname: __supportDir + "/..",
      basePath,
      spa: "200.html",
      silent: true,
      server: { ...serverDefaults },
    });
    const fileRes = await s.inject().get("/my-app/200.html");
    expect(fileRes.statusCode).toBe(200);
    const spaRes = await s.inject().get("/my-app/404.html");
    expect(spaRes.statusCode).toBe(200);
    await s.close();
  });

  test("works without dirname (run from project root)", async () => {
    const s = await init({
      dirs: ["test/dev-server/support"],
      basePath,
      silent: true,
      server: { ...serverDefaults },
    });
    const res = await s.inject().get("/my-app/200.html");
    expect(res.statusCode).toBe(200);
    await s.close();
  });
});
